g=[[0]*22 for _ in range(23)]
# Copy patterned 3x6 interior from the 7 frame into matching frames.
pattern=[[0,7,7,0,0,7],[7,7,0,7,7,7],[0,7,7,7,0,0]]
for color, top, left in [(5,2,2),(1,8,11)]:
    for c in range(left,left+8):
        g[top][c]=color; g[top+4][c]=color
    for r in range(top+1,top+4):
        g[r][left]=g[r][left+7]=color
        for k,v in enumerate(pattern[r-top-1]):
            g[r][left+1+k]=color if v else 0
# Keep the original patterned 7 frame.
for c in range(1,9): g[12][c]=g[16][c]=7
for r in range(13,16):
    g[r][1]=g[r][8]=7
for rr,row in enumerate(pattern):
    for k,v in enumerate(row): g[13+rr][2+k]=v
import json
print(json.dumps(g))
